//
// Concept:
// Minimal architectural skyline in blueprint style.
// Each cell generates ONE single 3D shape.
// One color only → maximum structural clarity.
// Complexity emerges from spatial subdivision, not decoration.
//
// Technique:
// - WEBGL
// - 2D recursive subdivision
// - Single extrusion per cell
// - Progressive drawing (construction over time)
//
// =========================================================


// ---------------------------------------------------------
// GLOBAL PARAMETERS
// ---------------------------------------------------------

// Number of times a final cell is replicated.
// This increases skyline density without adding complexity.
let CELL_REPETITIONS = 6;

// Arrays used for progressive generation
let cellsToGenerate = [];
let generatedCells = [];
let generateIndex = 0;


// ---------------------------------------------------------
// SKYLINE GENERATOR
// ---------------------------------------------------------
//
// Generates a centered horizontal skyline.
// Each "building" is a recursively subdivided 2D column
// that will later be extruded into 3D.
//

function generateSkyline(numBuildings = 8) {
  cellsToGenerate = [];
  generatedCells = [];
  generateIndex = 0;

  let buildingWidth = 45;

  for (let i = 0; i < numBuildings; i++) {
    // Center skyline on X axis
    let x = (i - numBuildings / 2) * buildingWidth;
    let w = buildingWidth;

    // Maximum height of the column
    let maxH = random(60, 200);

    // Start recursive subdivision
    recursiveTower(x, 0, w, maxH, int(random(3, 5)));
  }
}


// ---------------------------------------------------------
// 2D RECURSIVE SUBDIVISION
// ---------------------------------------------------------
//
// Performs structural subdivision only.
// No 3D geometry is created here.
//

function recursiveTower(x, y, w, h, depth) {
  if (depth > 1) {

    if (random() > 0.5) {
      // Horizontal split
      let r = random(0.35, 0.65);
      recursiveTower(x, y, w, h * r, depth - 1);
      recursiveTower(x, y + h * r, w, h * (1 - r), depth - 1);

    } else {
      // Volumetric setback
      let shrink = random(0.05, 0.12);
      recursiveTower(
        x + w * shrink,
        y + h * shrink,
        w * (1 - shrink * 2),
        h * (1 - shrink * 2),
        depth - 1
      );
    }

  } else {
    // Final cells → become architectural volumes
    for (let i = 0; i < CELL_REPETITIONS; i++) {
      cellsToGenerate.push({ x, y, w, h });
    }
  }
}


// ---------------------------------------------------------
// PROGRESSIVE DRAWING
// ---------------------------------------------------------
//
// Adds one architectural cell per frame.
// Produces a "construction process" effect.
//

function drawCellsProgressive() {
  if (generateIndex < cellsToGenerate.length) {
    let d = cellsToGenerate[generateIndex];
    generatedCells.push(
      new ArchitecturalCell3D(d.x, d.y, d.w, d.h)
    );
    generateIndex++;
  }

  // Vertical sorting improves visual clarity
  generatedCells.sort((a, b) => a.y - b.y);

  for (let c of generatedCells) {
    c.display();
  }
}


// ---------------------------------------------------------
// SETUP
// ---------------------------------------------------------

function setup() {
  createCanvas(400, 400, WEBGL);
  frameRate(30);
  colorMode(RGB);

  generateSkyline(8);
}


// ---------------------------------------------------------
// DRAW LOOP
// ---------------------------------------------------------

function draw() {
  // === Variant 5: Symmetric Kaleidoscope Portal ===
  // Applying kaleidoscope coordinate distortion
  uM_rot = frameCount * 0.005;
  push();
  translate(width/2, height/2);
  rotate(uM_rot);
  scale(1.1);
  translate(-width/2, -height/2);

  background(10, 10, 15); // Near-black background for blueprint contrast

  orbitControl(); // Free mouse navigation

  // Technical, non-realistic lighting
  ambientLight(60);
  directionalLight(255, 255, 255, -1, -1, -1);

  // Axonometric view
  rotateX(-PI / 6);
  rotateY(PI / 6);

  drawCellsProgressive();

  pop();
}


// ---------------------------------------------------------
// ARCHITECTURAL CELL 3D
// ---------------------------------------------------------
//
// One cell = one shape.
// No internal grammar.
// Purity is structural.
//

class ArchitecturalCell3D {
  constructor(x, y, w, h) {
    this.x = x;
    this.y = y;
    this.w = w;
    this.h = h;

    // Extrusion height
    this.height = random(20, 140);

    // Blueprint style
    this.strokeCol = color(0, 255, 180, 160);
    this.fillCol = color(0, 255, 180, 40);
    this.strokeW = 0.4;
  }

  display() {
    push();

    // Global positioning
    translate(this.x, -this.y+200, 0);

    stroke(this.strokeCol);
    strokeWeight(this.strokeW);
    fill(this.fillCol);

    // Geometric center of the volume
    translate(
      this.w / 2,
      -this.h / 2 - this.height / 2,
      0
    );

    // Single architectural volume
    box(
      this.w * 0.9,
      this.h * 0.9 + this.height,
      this.w * 0.9
    );

    pop();
  }
}

